#include <stdio.h>
#include <stdlib.h>

long binomial_coefficient(int n, int k) {
    if (k == 0 || k == n) {
        return 1;
    }
    long** memo = (long**)calloc(n + 1, sizeof(long*));
    for (int i = 0; i <= n; i++) {
        memo[i] = (long*)calloc(n + 1, sizeof(long));
    }
    for (int i = 0; i <= n; i++) {
        memo[i][0] = 1;
        memo[i][i] = 1;
    }
    for (int i = 2; i <= n; i++) {
        for (int j = 1; j < i; j++) {
            memo[i][j] = memo[i - 1][j - 1] + memo[i - 1][j];
        }
    }
    long result = memo[n][k];
    for (int i = 0; i <= n; i++) {
        free(memo[i]);
    }
    free(memo);
    return result;
}

int main(int argc, char* argv[]) {
    if (argc < 3) {
        printf("Usage: %s <n> <k>\n", argv[0]);
        return 1;
    }
    int n = atoi(argv[1]);
    int k = atoi(argv[2]);
    if (n < 0 || k < 0 || k > n) {
        printf("Invalid input\n");
        return 1;
    }
    long result = binomial_coefficient(n, k);
    printf("%ld\n", result);
    return 0;
}
